  "ge.forbidden": ["You don't have access to the gate for this society.", "आपको इस सोसाइटी के गेट की अनुमति नहीं है।", "તમને આ સોસાયટીના ગેટની પરવાનગી નથી."],
  "ge.not_found": ["This record isn't available.", "यह रिकॉर्ड उपलब्ध नहीं है।", "આ રેકોર્ડ ઉપલબ્ધ નથી."],
  "ge.invalid_plate": ["Enter at least 3 characters of the number plate.", "नंबर प्लेट के कम से कम 3 अक्षर लिखें।", "નંબર પ્લેટના ઓછામાં ઓછા 3 અક્ષર લખો."],
  "ge.invalid_label": ["Enter a slot name, like P-12.", "स्लॉट का नाम लिखें, जैसे P-12।", "સ્લોટનું નામ લખો, જેમ કે P-12."],
  "ge.restricted_visitor": ["This person is on the society's restricted list. The committee must decide.", "यह व्यक्ति सोसाइटी की प्रतिबंधित सूची में है। कमेटी को फ़ैसला करना होगा।", "આ વ્યક્તિ સોસાયટીની પ્રતિબંધિત યાદીમાં છે. કમિટીએ નિર્ણય લેવો પડશે."],
  "ge.needs_committee": ["Movers and restricted visitors need a committee decision.", "सामान शिफ़्ट करने वालों और प्रतिबंधित विज़िटर के लिए कमेटी का फ़ैसला ज़रूरी है।", "સામાન ખસેડનારા અને પ્રતિબંધિત વિઝિટર માટે કમિટીનો નિર્ણય જરૂરી છે."],
  "ge.reason_required": ["Please write a reason (at least 10 characters).", "कृपया कारण लिखें (कम से कम 10 अक्षर)।", "કૃપા કરી કારણ લખો (ઓછામાં ઓછા 10 અક્ષર)."],
  "ge.invalid_note": ["Please add a short note (at least 5 characters).", "कृपया छोटा नोट लिखें (कम से कम 5 अक्षर)।", "કૃપા કરી ટૂંકી નોંધ લખો (ઓછામાં ઓછા 5 અક્ષર)."],
  "ge.pass_not_valid_now": ["This regular pass isn't valid right now.", "यह नियमित पास अभी मान्य नहीं है।", "આ નિયમિત પાસ હમણાં માન્ય નથી."],
  "ge.already_inside": ["This person is already inside.", "यह व्यक्ति पहले से अंदर है।", "આ વ્યક્તિ પહેલેથી અંદર છે."],
  "ge.slot_taken": ["That parking slot is already in use.", "यह पार्किंग स्लॉट पहले से इस्तेमाल में है।", "આ પાર્કિંગ સ્લોટ પહેલેથી વપરાશમાં છે."],
  "ge.slot_not_found": ["That visitor slot isn't available.", "यह विज़िटर स्लॉट उपलब्ध नहीं है।", "આ વિઝિટર સ્લોટ ઉપલબ્ધ નથી."],
  "ge.not_allowed_offline": ["This needs a connection. Try again when you're online.", "इसके लिए इंटरनेट ज़रूरी है। ऑनलाइन होने पर फिर कोशिश करें।", "આ માટે ઇન્ટરનેટ જરૂરી છે. ઑનલાઇન થાઓ ત્યારે ફરી પ્રયાસ કરો."],
