  "ge.invalid_time": ["End time must be after start time.", "ख़त्म होने का समय शुरू होने के समय के बाद होना चाहिए।", "પૂરો થવાનો સમય શરૂ થવાના સમય પછી હોવો જોઈએ."],
  "ge.vehicle_not_found": ["That vehicle isn't registered in this society.", "यह वाहन इस सोसाइटी में रजिस्टर नहीं है।", "આ વાહન આ સોસાયટીમાં રજિસ્ટર નથી."],
  "ge.reauth_required": ["The committee signed out your gate session. Scan a new QR from them to continue.", "कमेटी ने आपके गेट सेशन से साइन आउट कर दिया। आगे बढ़ने के लिए उनसे नया QR स्कैन करें।", "કમિટીએ તમારા ગેટ સેશનમાંથી સાઇન આઉટ કર્યું. આગળ વધવા તેમની પાસેથી નવો QR સ્કેન કરો."],
  "ge.session_unbound": ["Please sign out and sign in again, then start your shift.", "कृपया साइन आउट करके फिर साइन इन करें, फिर अपनी शिफ़्ट शुरू करें।", "કૃપા કરી સાઇન આઉટ કરી ફરી સાઇન ઇન કરો, પછી તમારી શિફ્ટ શરૂ કરો."],
  "ge.not_assigned": ["This patrol round isn't assigned to you.", "यह गश्त राउंड आपको नहीं सौंपा गया है।", "આ પેટ્રોલ રાઉન્ડ તમને સોંપાયો નથી."],
  "ge.wrong_checkpoint_code": ["That checkpoint code doesn't match. Check the sign at the checkpoint.", "यह चेकपॉइंट कोड मेल नहीं खाता। चेकपॉइंट पर लगा बोर्ड देखें।", "આ ચેકપોઇન્ટ કોડ મેળ ખાતો નથી. ચેકપોઇન્ટ પરનું બોર્ડ જુઓ."],
  "ge.invalid_incident": ["Pick a severity and add a short note (at least 5 characters).", "गंभीरता चुनें और छोटा नोट लिखें (कम से कम 5 अक्षर)।", "ગંભીરતા પસંદ કરો અને ટૂંકી નોંધ લખો (ઓછામાં ઓછા 5 અક્ષર)."],
  "ge.invalid_schedule": ["Check the start time, window (10–720 min) and number of days (1–14).", "शुरू होने का समय, अवधि (10–720 मिनट) और दिनों की संख्या (1–14) जाँचें।", "શરૂ થવાનો સમય, અવધિ (10–720 મિનિટ) અને દિવસોની સંખ્યા (1–14) તપાસો."],
  "ge.guard_not_in_society": ["That guard isn't active in this society.", "यह गार्ड इस सोसाइटी में सक्रिय नहीं है।", "આ ગાર્ડ આ સોસાયટીમાં સક્રિય નથી."],
  "ge.invalid_checkpoints": ["Add between 1 and 30 checkpoints.", "1 से 30 चेकपॉइंट जोड़ें।", "1 થી 30 ચેકપોઇન્ટ ઉમેરો."],
  "ge.too_many_contacts": ["You can save up to 5 safety contacts.", "आप ज़्यादा से ज़्यादा 5 सुरक्षा संपर्क सेव कर सकते हैं।", "તમે વધુમાં વધુ 5 સુરક્ષા સંપર્ક સેવ કરી શકો છો."],
  "ge.invalid_credential": ["Enter the tag number (6–64 letters or digits).", "टैग नंबर लिखें (6–64 अक्षर या अंक)।", "ટેગ નંબર લખો (6–64 અક્ષર અથવા અંક)."],
